/**
 * A terminal whose `onData` reaches a PTY answers no XTVERSION and keeps the
 * optional VT extension replies off (src/renderer/utils/terminal-query-replies.ts
 * says why).
 *
 * The behavior cases drive a real `@xterm/headless` terminal, which shares
 * xterm's InputHandler. The color-scheme reply is generated by the browser core
 * only, so tests/ui/terminal-query-replies.spec.ts covers that half against the
 * browser bundle. See .claude/rules/xterm-query-replies.md.
 */

import { describe, it, expect } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { Terminal, type ITerminalOptions } from '@xterm/headless';
import { swallowXtversionQuery, TERMINAL_VT_EXTENSIONS } from '../../src/renderer/utils/terminal-query-replies';

const REPO_ROOT = path.resolve(__dirname, '../..');
const SCAN_ROOTS = ['src', 'demo', 'scripts'].map((directory) => path.join(REPO_ROOT, directory));
const SOURCE_EXTENSIONS = new Set(['.ts', '.tsx', '.js', '.mjs', '.cjs']);
const USE_TERMINAL_PATH = path.join(REPO_ROOT, 'src', 'renderer', 'hooks', 'useTerminal.ts');

/** The DCS reply xterm 6.1 sends for XTVERSION: `ESC P >|xterm.js(<version>) ESC \`. */
const XTVERSION_REPLY_MARKER = '>|xterm.js(';

function collectSourceFiles(directory: string): string[] {
  const files: string[] = [];
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    const fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      if (entry.name === 'node_modules') continue;
      files.push(...collectSourceFiles(fullPath));
    } else if (SOURCE_EXTENSIONS.has(path.extname(entry.name))) {
      files.push(fullPath);
    }
  }
  return files;
}

/** Source with comment lines and inline comments dropped, so a note that names a
 *  call can never satisfy the scan. */
function codeOnly(source: string): string {
  return source
    .split(/\r?\n/u)
    .filter((line) => {
      const trimmed = line.trim();
      return !(trimmed.startsWith('//') || trimmed.startsWith('*') || trimmed.startsWith('/*'));
    })
    .map((line) => line.replace(/\/\*.*?\*\//gu, '').replace(/\/\/.*$/u, ''))
    .join('\n');
}

/** `name.parser.registerCsiHandler({ prefix: '>', final: 'q' }`, the one-line
 *  handler a CommonJS script inlines because it cannot import the helper. Either
 *  quote style, either key order. */
function inlineSwallowPattern(terminalName: string): RegExp {
  const prefixKey = `prefix:\\s*['"]>['"]`;
  const finalKey = `final:\\s*['"]q['"]`;
  return new RegExp(
    `\\b${terminalName}\\.parser\\.registerCsiHandler\\(\\s*\\{\\s*(?:${prefixKey},\\s*${finalKey}|${finalKey},\\s*${prefixKey})\\s*,?\\s*\\}`,
    'u',
  );
}

function makeTerminal(options: ITerminalOptions = {}): Terminal {
  return new Terminal({ cols: 20, rows: 4, allowProposedApi: true, ...options });
}

/** Everything the terminal sends back while it parses `data`. */
async function repliesTo(terminal: Terminal, data: string): Promise<string> {
  const replies: string[] = [];
  const subscription = terminal.onData((reply) => replies.push(reply));
  try {
    await new Promise<void>((resolve) => terminal.write(data, resolve));
  } finally {
    subscription.dispose();
  }
  return replies.join('');
}

describe('swallowXtversionQuery', () => {
  it('starts from an xterm that answers XTVERSION, so the swallow is not vacuous', async () => {
    const terminal = makeTerminal();
    try {
      expect(await repliesTo(terminal, '\x1b[>q')).toContain(XTVERSION_REPLY_MARKER);
    } finally {
      terminal.dispose();
    }
  });

  it('answers neither CSI > q nor CSI > 0 q once swallowed', async () => {
    const terminal = makeTerminal({ vtExtensions: TERMINAL_VT_EXTENSIONS });
    swallowXtversionQuery(terminal);
    try {
      expect(await repliesTo(terminal, '\x1b[>q')).toBe('');
      expect(await repliesTo(terminal, '\x1b[>0q')).toBe('');
    } finally {
      terminal.dispose();
    }
  });

  it('still answers device attributes, including DA2, which shares the > prefix', async () => {
    const terminal = makeTerminal({ vtExtensions: TERMINAL_VT_EXTENSIONS });
    swallowXtversionQuery(terminal);
    try {
      expect(await repliesTo(terminal, '\x1b[>c')).toMatch(/^\x1b\[>[\d;]+c$/u);
      expect(await repliesTo(terminal, '\x1b[c')).toMatch(/^\x1b\[\?[\d;]+c$/u);
    } finally {
      terminal.dispose();
    }
  });
});

describe('TERMINAL_VT_EXTENSIONS', () => {
  it('pins every optional extension that can reply into the PTY off', () => {
    expect(TERMINAL_VT_EXTENSIONS).toEqual({
      kittyKeyboard: false,
      win32InputMode: false,
      colorSchemeQuery: false,
    });
  });

  it('reaches the parser: the kitty keyboard query goes unanswered with it and answered without it', async () => {
    // Positive control: with the extension on, the same query gets a reply, so
    // the silence below is the option at work and not a parser that ignores it.
    const enabled = makeTerminal({ vtExtensions: { kittyKeyboard: true } });
    const pinned = makeTerminal({ vtExtensions: TERMINAL_VT_EXTENSIONS });
    try {
      expect(await repliesTo(enabled, '\x1b[?u')).toMatch(/^\x1b\[\?\d+u$/u);
      expect(await repliesTo(pinned, '\x1b[?u')).toBe('');
    } finally {
      enabled.dispose();
      pinned.dispose();
    }
  });
});

describe('every terminal whose onData is consumed swallows XTVERSION', () => {
  it('each Terminal whose onData is wired swallows CSI > q and pins the extensions off', () => {
    const visited: string[] = [];
    const violations: string[] = [];
    for (const filePath of SCAN_ROOTS.flatMap((root) => collectSourceFiles(root))) {
      const source = fs.readFileSync(filePath, 'utf-8');
      if (!source.includes('Terminal')) continue;
      const code = codeOnly(source);
      const relativePath = path.relative(REPO_ROOT, filePath).replace(/\\/g, '/');
      // Per terminal, not per file: a second terminal in the same file must not
      // ride on the first one's swallow.
      for (const construction of code.matchAll(/(\w+)\s*=\s*new\s+\w*Terminal\s*\(/gu)) {
        const terminalName = construction[1];
        if (!new RegExp(`\\b${terminalName}\\.onData\\s*\\(`, 'u').test(code)) continue;
        if (!visited.includes(relativePath)) visited.push(relativePath);
        // The TS helper, or the same one-line handler inlined where a CommonJS
        // script cannot import it.
        const swallows = new RegExp(`\\bswallowXtversionQuery\\(\\s*${terminalName}\\s*\\)`, 'u').test(code)
          || inlineSwallowPattern(terminalName).test(code);
        if (!swallows) violations.push(`${relativePath} (${terminalName}): no XTVERSION swallow`);
        // The constructor options: the shared constant, or every one of its keys
        // spelled out as false where a CommonJS script cannot import it.
        const constructionStart = construction.index ?? 0;
        const constructionEnd = code.indexOf('});', constructionStart);
        const constructorOptions = code.slice(constructionStart, constructionEnd === -1 ? undefined : constructionEnd);
        const pinsExtensions = constructorOptions.includes('vtExtensions: TERMINAL_VT_EXTENSIONS')
          || Object.keys(TERMINAL_VT_EXTENSIONS).every((key) => new RegExp(`\\b${key}:\\s*false\\b`, 'u').test(constructorOptions));
        if (!pinsExtensions) violations.push(`${relativePath} (${terminalName}): vtExtensions not pinned off`);
      }
    }
    // Pins that the scan still finds the real sites, so it cannot pass vacuously.
    expect(visited).toEqual(expect.arrayContaining([
      'src/renderer/hooks/useTerminal.ts',
      'scripts/probe-terminal-peek-grid.js',
      'scripts/probe-claude-headless-statusline.js',
    ]));
    expect(
      violations,
      'A terminal whose onData reaches a PTY must swallow XTVERSION and be constructed with ' +
      'every TERMINAL_VT_EXTENSIONS key off (src/renderer/utils/terminal-query-replies.ts), or ' +
      'xterm 6.1 answers capability queries for that session only. ' +
      'See .claude/rules/xterm-query-replies.md.',
    ).toEqual([]);
  });

  it('useTerminal pins the extensions and swallows the query before it opens the terminal', () => {
    const code = codeOnly(fs.readFileSync(USE_TERMINAL_PATH, 'utf-8'));
    const constructAt = code.indexOf('new Terminal({');
    const constructEnd = code.indexOf('});', constructAt);
    expect(constructAt, 'new Terminal({ not found in useTerminal.ts').toBeGreaterThan(-1);
    expect(code.slice(constructAt, constructEnd)).toContain('vtExtensions: TERMINAL_VT_EXTENSIONS');
    const swallowAt = code.indexOf('swallowXtversionQuery(terminal)');
    const openAt = code.indexOf('terminal.open(');
    expect(swallowAt).toBeGreaterThan(constructEnd);
    expect(openAt).toBeGreaterThan(swallowAt);
  });
});
